function colLetter(n){var s='';while(n>0){var m=(n-1)%26;s=String.fromCharCode(65+m)+s;n=(n-m-1)/26;}return s;}
var sh=ss.getSheetByName('BS-CF-WC');
// P&L links
var revFormulas=[[]], codFormulas=[[]];
for(var c=4;c<=10;c++){
  var col=colLetter(c);
  revFormulas[0].push("='P&L'!"+col+"70");
  codFormulas[0].push("=-'P&L'!"+col+"71");
}
sh.getRange('D106:J106').setFormulas(revFormulas);
sh.getRange('D107:J107').setFormulas(codFormulas);

// Historical balances D:E
var histDE = [
  ['=D9','=E9'],
  ['=D10','=E10'],
  ['=D11','=E11'],
  ['=SUM(D110:D112)','=SUM(E110:E112)'],
  ['=D23','=E23'],
  ['=D24','=E24'],
  ['=D25','=E25'],
  ['=D26','=E26'],
  ['=D27','=E27'],
  ['=SUM(D115:D119)','=SUM(E115:E119)'],
  ['=D113-D120','=E113-E120']
];
sh.getRange('D110:E113').setFormulas(histDE.slice(0,4));
sh.getRange('D115:E120').setFormulas(histDE.slice(4,10));
sh.getRange('D122:E122').setFormulas([histDE[10]]);
sh.getRange('D124').clearContent();
sh.getRange('E124').setFormula('=D122-E122');

// Forecast balances F:J based on driver block
var forecastCols=['F','G','H','I','J'];
function rowFormulas(make){return [forecastCols.map(function(col,i){return make(col,i);})];}
sh.getRange('F110:J110').setFormulas(rowFormulas(function(col){return '='+col+'129*'+col+'106/365';}));
sh.getRange('F111:J111').setFormulas(rowFormulas(function(col){return '='+col+'131';}));
sh.getRange('F112:J112').setFormulas(rowFormulas(function(col){return '='+col+'134';}));
sh.getRange('F113:J113').setFormulas(rowFormulas(function(col){return '=SUM('+col+'110:'+col+'112)';}));
sh.getRange('F115:J115').setFormulas(rowFormulas(function(col){return '='+col+'137*'+col+'107/365';}));
sh.getRange('F116:J116').setFormulas(rowFormulas(function(col){return '='+col+'139';}));
sh.getRange('F117:J117').setFormulas(rowFormulas(function(col){return '='+col+'142';}));
sh.getRange('F118:J118').setFormulas(rowFormulas(function(col){return '='+col+'145';}));
sh.getRange('F119:J119').setFormulas(rowFormulas(function(col){return '='+col+'147';}));
sh.getRange('F120:J120').setFormulas(rowFormulas(function(col){return '=SUM('+col+'115:'+col+'119)';}));
sh.getRange('F122:J122').setFormulas(rowFormulas(function(col){return '='+col+'113-'+col+'120';}));
sh.getRange('F124:J124').setFormulas([['=E122-F122','=F122-G122','=G122-H122','=H122-I122','=I122-J122']]);
SpreadsheetApp.flush();
